(function(SK){
  'use strict';
  const {isoDay,addDays,monday,daysBetween,dateLabel,clone,uid,sports,goals}=SK;
  const root=document.getElementById('root'),modalRoot=document.getElementById('modal-root');
  let state=null,demo=false,view='overview',busy=false,anchor=isoDay(),selectedDay=isoDay();
  let calendarMode=innerWidth<640?'week':'month',syncLabel='Opgeslagen',modalLocked=false,focusBefore=null,shareUrl='',lastFocusSync=0;
  let recovery=/type=(recovery|invite)/.test(location.hash),toastTimer;
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const num=n=>new Intl.NumberFormat('nl-NL',{maximumFractionDigits:1}).format(n||0);
  const icons={
    compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2.5 5.5L8 16l2.5-5.5Z"/>',
    grid:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',
    calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-13 5h2m4 0h2"/>',
    spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5ZM20 2v4m-2-2h4"/>',
    chart:'<path d="M4 3v17h17M8 15l4-5 4 2 5-7"/>',
    settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',
    run:'<circle cx="15" cy="4" r="2"/><path d="m12 9 3 4 4 1M7 10l4-2 3 1-4 7-5 4m5-4 5 1 1 4"/>',
    strength:'<path d="M7 8v8m10-8v8M7 12h10M4 6v12m16-12v12M2 10v4m20-4v4"/>',
    cycle:'<circle cx="5" cy="16" r="4"/><circle cx="19" cy="16" r="4"/><path d="m5 16 5-9 5 9H5m5-9 8 1 1 8M8 5h4m3-3h3l1 5"/>',
    walk:'<circle cx="13" cy="4" r="2"/><path d="m10 10 2-3 3 4 4 1m-7-5-2 8-3 6m3-6 5 2 1 5M7 13l3-3"/>',
    target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
    shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',
    cloud:'<path d="M7 18a5 5 0 1 1 1-10 6 6 0 0 1 11 2 4 4 0 0 1 0 8M12 11v10m-3-3 3 3 3-3"/>',
    share:'<path d="M12 16V3m-5 5 5-5 5 5M5 13v7h14v-7"/>',
    plus:'<path d="M12 5v14M5 12h14"/>',
    arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
    left:'<path d="m15 6-6 6 6 6"/>',right:'<path d="m9 6 6 6-6 6"/>',
    check:'<path d="m5 12 4 4L19 6"/>', close:'<path d="m6 6 12 12M18 6 6 18"/>',
    lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',
    logout:'<path d="M9 4H4v16h5m6-13 5 5-5 5M9 12h11"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
    trash:'<path d="M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7"/>',
    refresh:'<path d="M20 7v5h-5M4 17v-5h5M5 8a7 7 0 0 1 12-3l3 3M4 16l3 3a7 7 0 0 0 12-3"/>',
    info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>'
  };
  const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.run}</svg>`;
  const btn=(label,action,extra='',className='')=>`<button type="button" class="btn ${className}" data-action="${action}" ${extra}>${label}</button>`;
  const brand=mobile=>`<div class="brand ${mobile?'mobile-brand':''}"><span class="brand-mark">${icon('compass',24)}</span><span>SportKompas</span></div>`;
  const days=['Maandag','Dinsdag','Woensdag','Donderdag','Vrijdag','Zaterdag','Zondag'];
  const shortDays=['Ma','Di','Wo','Do','Vr','Za','Zo'];
  const opts=(obj,value)=>Object.entries(obj).map(([k,v])=>`<option value="${esc(k)}" ${k===String(value)?'selected':''}>${esc(v)}</option>`).join('');
  function toast(text){clearTimeout(toastTimer);const el=document.getElementById('toast');el.textContent=text;el.classList.add('visible');toastTimer=setTimeout(()=>el.classList.remove('visible'),5500);}
  function showError(form,text){if(!form.isConnected){toast(text);return;}const el=form.querySelector('.form-error');if(el){el.textContent=text;el.scrollIntoView({block:'nearest'});}else toast(text);}
  function showModal(title,subtitle,content,{wide=false,locked=false}={}){
    focusBefore=document.activeElement;modalLocked=locked;
    modalRoot.innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">${esc(title)}</h2><p>${esc(subtitle)}</p></div>${locked?'':btn(icon('close'),'close-modal','aria-label="Sluiten"','ghost icon-btn')}</div>${content}</section></div>`;
    document.body.style.overflow='hidden';setTimeout(()=>modalRoot.querySelector('input:not([type=checkbox]),select,button')?.focus(),20);
  }
  function closeModal(){if(busy)return;modalRoot.innerHTML='';document.body.style.overflow='';modalLocked=false;focusBefore?.focus();}
  async function commit(candidate,message='Opgeslagen'){
    SK.validateState(candidate);
    if(demo){state=candidate;syncLabel='Alleen demo';}
    else {try{state=await SK.DB.save(candidate);syncLabel='Opgeslagen';}catch(e){if(e.code==='CONFLICT'){const data=await SK.DB.load();state=data.state;render();}throw e;}}
    render();if(message)toast(message);
  }
  function renderAuth(){
    state=null;shareUrl='';
    root.innerHTML=`<div class="auth-layout"><section class="auth-story">${brand(false)}<h1>Jouw ritme.<br>Jouw doel.<br><em>Een plan dat<br>meebeweegt.</em></h1><p>Niet elke training gaat zoals gepland. Je agenda mag zich aanpassen aan jou. Niet andersom.</p><div class="story-preview"><div class="eyebrow" style="color:#b8d49f">Je hebt toch bewogen</div><div style="margin:13px 0"><span class="preview-strike">10 km gepland</span><span class="preview-new">5 km gelopen</span></div><p class="small" style="color:#b6cdbb">Registreer wat lukte. De planner bekijkt de komende trainingen opnieuw, zonder inhaalschuld.</p></div><div class="story-foot">Persoonlijk account &nbsp; / &nbsp; Jouw vaste momenten &nbsp; / &nbsp; Jouw tempo</div></section><main class="auth-form-wrap" id="main"><div class="auth-form"><div class="eyebrow">Welkom bij jouw sportagenda</div><h2>Goed je te zien.</h2><p>Log in op je eigen account. Je schema, resultaten en doelen zijn alleen van jou.</p><form id="login-form"><div class="form-error" role="alert"></div><label>E-mailadres<input name="email" type="email" autocomplete="username" placeholder="naam@voorbeeld.nl" required></label><label>Wachtwoord<input name="password" type="password" autocomplete="current-password" placeholder="Jouw persoonlijke wachtwoord" required></label><button class="btn primary" type="submit">Inloggen ${icon('arrow',17)}</button></form><div class="button-row" style="justify-content:center;margin-top:12px">${btn('Wachtwoord vergeten?','recover','','ghost compact')}</div>${SK.DB.configured()?'':`<div class="notice small mt">De app is nog niet gekoppeld aan Supabase. Vul de publieke projectgegevens in <strong>config.js</strong> in. De demo werkt direct.</div>`}<div class="auth-bottom">${btn('Bekijk de interactieve demo '+icon('arrow',16),'start-demo','','ghost')}<p>Fictieve gegevens. Geen account nodig voor de demo.</p></div><div class="security-note mt">${icon('shield',16)}<span>Alleen uitgenodigde accounts. Geen openbare registratie. Op een gedeelde computer: log uit als je klaar bent.</span></div></div></main></div>`;
  }
  function shell(){
    const nav=[['overview','grid','Overzicht'],['calendar','calendar','Agenda'],['coach','spark','Coach'],['progress','chart','Voortgang'],['settings','settings','Instellingen']];
    const name=state.profile?.name||'Mijn account', initials=name.slice(0,1).toUpperCase();
    return `<div class="app-shell"><aside class="sidebar">${brand(false)}<div class="brand-sub">JOUW RITME, JOUW DOEL</div><nav class="nav" aria-label="Hoofdnavigatie">${nav.map(([v,i,t])=>`<button data-action="nav" data-view="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''} title="${t}">${icon(i)}<span>${t}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="personal-note">${icon('shield',20)}<strong>Jouw eigen koers</strong>Geen gedeelde doelen. Geen vergelijking. Alleen jouw planning en voortgang.</div><div class="sidebar-account"><div class="avatar">${esc(initials)}</div><div class="account-text"><strong>${esc(name)}</strong><span class="tiny" style="color:#93ad9c">${demo?'Demo-account':'Persoonlijk account'}</span></div><button title="Uitloggen" aria-label="Uitloggen" data-action="logout">${icon('logout',18)}</button></div></div></aside><div class="content"><header class="topbar"><div class="breadcrumb">Mijn sportomgeving &nbsp; / &nbsp; <b>${nav.find(n=>n[0]===view)?.[2]||'Overzicht'}</b></div>${brand(true)}<div class="top-actions"><div class="sync-state"><i class="sync-dot"></i>${esc(demo?'Demogegevens':navigator.onLine?syncLabel:'Offline - niet opslaan')}</div>${btn(icon('refresh',17),'sync','title="Synchroniseren" aria-label="Synchroniseren"','icon-btn')}${btn(icon('share',16)+'<span>Agenda koppelen</span>','share','title="Agenda koppelen" aria-label="Agenda koppelen"')}${btn(icon('logout',16),'logout','aria-label="Uitloggen" title="Uitloggen"','icon-btn')}</div></header>${demo?'<div class="demo-banner"><span><strong>Interactieve demo.</strong> Alle trainingen en afstanden zijn fictieve voorbeelden.</span><button data-action="reset-demo">Demo herstellen</button></div>':''}<main id="main">${page()}</main><footer class="footer-note">SportKompas v1.0 &nbsp; &middot; &nbsp; Automatische planner, geen medisch advies &nbsp; &middot; &nbsp; Europe/Amsterdam</footer></div></div>`;
  }
  function render(){if(!state){renderAuth();return;}if(!state.profile)view='settings';root.innerHTML=shell();}
  function page(){return view==='calendar'?calendarPage():view==='coach'?coachPage():view==='progress'?progressPage():view==='settings'?settingsPage():overviewPage();}
  function heading(title,sub,actions=''){return `<div class="page-heading"><div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div>${actions||`<div class="date-label">${dateLabel(isoDay(),{weekday:'long'})}</div>`}</div>`;}
  function upcoming(){return state.workouts.filter(w=>['planned','held'].includes(w.status)&&w.date>=isoDay()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));}
  function weeklyStats(){const m=monday(isoDay()),end=addDays(m,6);const ws=state.workouts.filter(w=>w.date>=m&&w.date<=end&&w.status!=='cancelled');return {planned:ws.filter(w=>w.sport==='run').reduce((a,w)=>a+(w.actual?.plannedKm??w.km),0),actual:ws.filter(w=>w.sport==='run').reduce((a,w)=>a+(w.actual?.km||0),0),minutes:ws.reduce((a,w)=>a+(w.actual?.minutes||0),0),done:ws.filter(w=>w.status==='done').length,total:ws.length};}
  function tags(w){let out='';if(w.status==='done')out+='<span class="tag">Afgerond</span>';if(w.status==='skipped')out+='<span class="tag muted">Overgeslagen</span>';if(w.status==='held')out+='<span class="tag red">Gepauzeerd</span>';if(w.adaptation&&w.km<w.baseKm)out+='<span class="tag lime">Aangepast</span>';if(w.locked)out+=`<span class="tag amber">${icon('lock',10)} Vastgezet</span>`;else if(w.source==='plan')out+='<span class="tag muted">Vast moment</span>';if(w.status==='planned'&&w.date<isoDay())out+='<span class="tag amber">Nog invullen</span>';return out?`<div class="tags">${out}</div>`:'';}
  function workoutCard(w,{date=true}={}){
    const actual=w.actual&&['done','skipped'].includes(w.status),km=actual?w.actual.km:w.km,min=actual?w.actual.minutes:w.minutes;
    const action=w.date<=isoDay()&&w.status!=='cancelled'?'log':'detail';
    return `<div class="workout ${esc(w.status)}"><div class="sport-icon ${esc(w.sport)}">${icon(w.status==='done'?'check':w.sport,21)}</div><div class="workout-info"><strong>${esc(w.title)}</strong><div class="workout-meta">${date?esc(dateLabel(w.date,{weekday:'short'}))+' &middot; ':''}${esc(w.time)} &middot; ${num(min)} min</div>${tags(w)}</div><div class="workout-distance">${num(w.sport==='run'?km:min)} <small>${w.sport==='run'?'km':'min'}</small></div>${btn(actual?'Bekijken':action==='log'?'Invullen':icon('right',16),action,`data-id="${esc(w.id)}" aria-label="${action==='log'?'Training registreren':'Training bekijken'}"`,'compact')}</div>`;
  }
  function weekStrip(){const m=monday(isoDay());return `<div class="week-strip">${Array.from({length:7},(_,i)=>{const day=addDays(m,i),ws=state.workouts.filter(w=>w.date===day&&w.status!=='cancelled');return `<button class="day-chip ${day===isoDay()?'today':''} ${selectedDay===day?'selected':''}" data-action="day" data-date="${day}" aria-label="${esc(dateLabel(day,{weekday:'long'}))}"><span>${shortDays[i]}</span><strong>${+day.slice(-2)}</strong><span class="dots">${ws.slice(0,3).map(w=>`<i class="dot ${w.sport!=='run'?'alt':''}"></i>`).join('')}</span></button>`;}).join('')}</div>`;}
  function overviewPage(){
    if(!state.profile)return settingsPage();const p=state.profile,next=upcoming()[0],stats=weeklyStats();const ws=state.workouts.filter(w=>w.date===selectedDay&&w.status!=='cancelled').sort((a,b)=>a.time.localeCompare(b.time));const last=state.adjustments[0],warnings=SK.warnings(state);
    return heading(`Jouw ritme, ${p.name.replace(' (demo)','')}.`,'Een goed plan beweegt mee met het echte leven.')+`${state.hold?'<div class="notice danger">Je planning staat gepauzeerd. Bekijk Coach voordat je weer opbouwt.</div>':''}<div class="dashboard-grid"><div class="stack"><div><section class="card hero"><div class="eyebrow">${state.hold?'Even pas op de plaats':next?'Jouw volgende stap':'Ruimte voor beweging'}</div><h2>${state.hold?'Herstel gaat voor.':next?esc(next.title):'Maak ruimte voor je doel.'}</h2><p>${state.hold?'Geen inhaalkilometers. Hervat je planning bewust wanneer dat weer passend is.':next?`${esc(dateLabel(next.date,{weekday:'long'}))} om ${esc(next.time)} &middot; ${num(next.sport==='run'?next.km:next.minutes)} ${next.sport==='run'?'km':'min'} &middot; ${next.sport==='run'?'rustig tempo':esc(sports[next.sport])}`:'Je eigen vaste momenten en startniveau vormen de basis.'}</p><div class="hero-footer">${state.hold?btn('Bekijk je planning '+icon('arrow',16),'nav','data-view="coach"','lime'):next?btn(next.date<=isoDay()?'Training invullen '+icon('arrow',16):'Bekijk training '+icon('arrow',16),next.date<=isoDay()?'log':'detail',`data-id="${esc(next.id)}"`,'lime'):btn('Plan je week '+icon('arrow',16),'nav','data-view="settings"','lime')}<span class="small">${p.autoAdapt?'Automatisch aanpassen staat aan':'Handmatig beoordelen staat aan'}</span></div></section><div class="mini-stats"><div class="stat-card"><div class="stat-top">Deze week gelopen ${icon('run',16)}</div><div class="stat-number">${num(stats.actual)} <small>km</small></div><div class="stat-caption">${num(stats.planned)} km gepland</div><div class="progress-line"><span style="width:${Math.min(100,stats.planned?stats.actual/stats.planned*100:0)}%"></span></div></div><div class="stat-card"><div class="stat-top">Trainingen ${icon('check',16)}</div><div class="stat-number">${stats.done} <small>/ ${stats.total}</small></div><div class="stat-caption">afgerond deze week</div></div><div class="stat-card"><div class="stat-top">Bewogen ${icon('clock',16)}</div><div class="stat-number">${num(stats.minutes)} <small>min</small></div><div class="stat-caption">alle geregistreerde sporten</div></div></div></div><section class="card"><div class="card-header"><div><h2>Jouw week</h2><p>${dateLabel(monday(isoDay()))} - ${dateLabel(addDays(monday(isoDay()),6))}</p></div>${btn('Hele agenda '+icon('arrow',14),'nav','data-view="calendar"','ghost compact')}</div>${weekStrip()}<div class="section-row"><h3>${selectedDay===isoDay()?'Vandaag':dateLabel(selectedDay,{weekday:'long'})}</h3>${btn(icon('plus',15)+' Activiteit','add-workout',`data-date="${selectedDay}"`,'ghost compact')}</div><div class="workout-list">${ws.length?ws.map(w=>workoutCard(w,{date:false})).join(''):'<div class="empty">Geen sportmoment gepland.<br>Je hoeft niet elke vrije dag op te vullen.</div>'}</div></section><section class="card"><div class="card-header"><h2>Daarna op de planning</h2><span class="tag muted">Komende dagen</span></div><div class="workout-list">${upcoming().filter(w=>w.date>isoDay()).slice(0,3).map(w=>workoutCard(w)).join('')||'<div class="empty">Stel je vaste sportmomenten in.</div>'}</div></section></div><div class="stack"><section class="card coach-card"><div class="coach-glyph">${icon('spark',23)}</div><div class="eyebrow" style="color:#708850;margin-bottom:10px">De planner denkt mee</div><h3>${esc(last?.title||'Niet meer doen. Passend doen.')}</h3><p>${esc(last?.detail||'Vul na je training in wat je werkelijk hebt gedaan. De planner kijkt naar afstand, inspanning en de reden van een afwijking.')}</p>${btn('Bekijk aanpassingen '+icon('arrow',14),'nav','data-view="coach"','ghost compact mt')}<div class="card-footer">Vaste regels &middot; automatische beoordeling na registratie</div></section><section class="card"><div class="card-header"><h2>Jouw doel</h2>${icon('target',20)}</div><div class="goal-row"><div class="goal-icon">${icon('target',28)}</div><div><h3>${esc(goals[p.goal])}</h3><p>${p.raceDate?dateLabel(p.raceDate,{year:'numeric'}):'Op jouw eigen tempo'}</p></div></div><div class="key-value"><span>Huidige basis</span><strong>${num(p.baseWeeklyKm)} km/week</strong></div><div class="key-value"><span>Vaste sportmomenten</span><strong>${state.slots.length} per week</strong></div><div class="key-value"><span>Doeldatum</span><strong>${p.raceDate?`${daysBetween(isoDay(),p.raceDate)} dagen`:'Geen einddatum'}</strong></div>${btn('Mijn doel aanpassen','nav','data-view="settings"','ghost compact mt')}</section><section class="card"><div class="card-header"><h2>Goed om te weten</h2>${icon('info',18)}</div><p class="small muted">${warnings.length?esc(warnings[0]):'Een kortere training is informatie, geen mislukking. Vul ook in waarom je minder deed: tijdgebrek is iets anders dan zware benen.'}</p><div class="divider"></div><div class="security-note">${icon('shield',17)}<span>Je collega heeft een eigen account, een eigen doel en een volledig eigen planning.</span></div></section></div></div>`;
  }
  function calendarPage(){
    const first=anchor.slice(0,7)+'-01';let start,end,title;
    if(calendarMode==='month'){start=monday(first);end=addDays(start,41);title=dateLabel(first,{month:'long',year:'numeric',day:undefined});}else{start=monday(anchor);end=addDays(start,6);title=`${dateLabel(start)} - ${dateLabel(end)}`;}
    const ws=state.workouts.filter(w=>w.date>=start&&w.date<=end&&w.status!=='cancelled').sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));
    let content='';
    if(calendarMode==='month')content=`<div class="calendar-grid">${shortDays.map(d=>`<div class="calendar-label">${d}</div>`).join('')}${Array.from({length:42},(_,i)=>{const day=addDays(start,i);return `<div class="calendar-cell ${day===isoDay()?'today':''} ${day.slice(0,7)!==first.slice(0,7)?'outside':''}"><span class="cell-date">${+day.slice(-2)}</span>${ws.filter(w=>w.date===day).map(w=>`<button class="calendar-event ${esc(w.sport)} ${esc(w.status)}" data-action="detail" data-id="${esc(w.id)}"><span class="time">${esc(w.time)}${w.status==='done'?' &#10003;':''}</span><br>${esc(sports[w.sport])}${w.sport==='run'?` ${num(w.actual?.km??w.km)} km`:''}${w.status==='held'?'<br>Gepauzeerd':''}</button>`).join('')}</div>`;}).join('')}</div>`;
    else content=Array.from({length:7},(_,i)=>{const day=addDays(start,i),list=ws.filter(w=>w.date===day);return `<div class="list-day-label"><span>${esc(dateLabel(day,{weekday:'long'}))}${day===isoDay()?' &middot; vandaag':''}</span>${btn(icon('plus',13),'add-workout',`data-date="${day}" aria-label="Activiteit toevoegen op ${day}"`,'ghost compact')}</div><div class="workout-list">${list.length?list.map(w=>workoutCard(w,{date:false})).join(''):'<p class="small muted" style="padding:5px 0 10px">Vrij / herstel</p>'}</div>`;}).join('');
    return heading('Jouw sportagenda.','Vaste momenten. Ruimte om aan te passen.',btn(icon('plus',16)+' Activiteit','add-workout','','primary'))+`<section class="card"><div class="toolbar"><div class="button-row">${btn(icon('left',16),'cal-prev','aria-label="Vorige periode"','icon-btn')}<div class="week-title">${esc(title)}</div>${btn(icon('right',16),'cal-next','aria-label="Volgende periode"','icon-btn')}${btn('Vandaag','cal-today','','ghost compact')}</div><div class="segmented"><button class="${calendarMode==='week'?'active':''}" data-action="cal-mode" data-mode="week">Week</button><button class="${calendarMode==='month'?'active':''}" data-action="cal-mode" data-mode="month">Maand</button></div></div>${content}</section><div class="notice mt">Wijzig trainingen in SportKompas. Het agenda-abonnement neemt deze wijzigingen over zodra je agenda-app ververst. Bestaande priveafspraken worden in deze versie niet ingelezen.</div>`;
  }
  function coachPage(){
    const warnings=SK.warnings(state),last=state.adjustments;
    return heading('Een plan dat meebeweegt.','Automatische planningsregels, met optionele AI-uitleg.')+`${warnings.map(x=>`<div class="notice ${state.hold?'danger':'warning'}">${esc(x)}</div>`).join('')}<div class="settings-grid"><div class="stack"><section class="card coach-card"><div class="card-header"><div><h2>${state.hold?'Je planning staat op pauze':'Jij beweegt. Je schema beweegt mee.'}</h2><p>Automatisch na het registreren van een activiteit</p></div>${icon('spark',27)}</div><p>De planner kijkt naar werkelijk gelopen kilometers, je ervaren inspanning en waarom je afweek. Dagen en begintijden van vaste sportmomenten blijven staan. Een gemiste 5 km wordt nooit zomaar bij je volgende training opgeteld.</p><div class="button-row mt">${state.hold?btn('Planning bewust hervatten','resume','','primary'):btn('Schema nu opnieuw beoordelen','recalculate','','primary')}</div></section><section class="card"><div class="card-header"><h2>Wat is er aangepast?</h2><span class="tag muted">${last.length} beoordelingen</span></div>${last.length?last.slice(0,20).map(a=>`<article class="audit"><div class="audit-head"><h3>${esc(a.title)}</h3><span class="tiny muted">${esc(new Date(a.at).toLocaleString('nl-NL',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}))}</span></div><p>${esc(a.detail)}</p>${a.changes.slice(0,8).map(c=>`<div class="change"><span>${esc(c.title)} &middot; ${esc(dateLabel(c.after.date))}</span><b>${c.after.status==='held'?'Gepauzeerd':c.after.status==='cancelled'?'Verwijderd':`${num(c.before.km)} &rarr; ${num(c.after.km)} km`}</b></div>`).join('')}${a.changes.length>8?`<p class="tiny">En ${a.changes.length-8} andere wijzigingen; zichtbaar in je agenda.</p>`:''}</article>`).join(''):'<div class="empty">Vul een training in om je eerste beoordeling te zien.</div>'}</section></div><div class="stack"><section class="card"><div class="card-header"><div><h2>Vraag het aan AI</h2><p>${demo?'Demo: geen externe AI-aanroepen':SPORT_CONFIG.enableAI?'Optionele uitleg via OpenAI':'Nog niet aangesloten'}</p></div>${icon('spark',20)}</div><p class="small muted mb">AI kan je planning toelichten, maar wijzigt deze niet zelfstandig. De automatische planner hierboven werkt ook zonder AI-abonnement of API-sleutel.</p><form id="coach-form"><div class="form-error" role="alert"></div><label>Je vraag<textarea name="question" maxlength="1200" placeholder="Waarom is mijn volgende duurloop korter?" required></textarea></label><label class="checkline small mt"><input name="consent" type="checkbox" required><span>Mijn vraag en een beperkte samenvatting van mijn trainingen mogen voor deze vraag naar OpenAI. Naam, e-mail en trainingsnotities worden niet meegestuurd. Zet zelf geen gevoelige persoonsgegevens in je vraag.</span></label><button class="btn primary mt" type="submit" ${!demo&&!SPORT_CONFIG.enableAI?'disabled':''}>Vraag versturen ${icon('arrow',16)}</button></form><div id="ai-answer"></div></section><section class="card"><h3>Zo werkt deze versie</h3><p class="small muted mt">Het automatische schema gebruikt controleerbare regels, geen taalmodel. De 3% opbouw en lichtere weken zijn ontwerpkeuzes, geen bewezen veiligheidsgrens. Het model kent je lichaam, blessurehistorie en herstel niet.</p><div class="divider"></div><p class="small muted">Hardlopen wordt in kilometers gepland. Andere sporten zijn als tijdsblokken toegevoegd en tellen mee in je sportminuten, maar worden niet omgezet naar hardloopkilometers.</p><div class="divider"></div><p class="small muted">Voor een marathon is beoordeling door een looptrainer verstandig. De app belooft niet dat een gekozen datum of afstand haalbaar is.</p></section></div></div>`;
  }
  function progressPage(){
    const today=isoDay(),m=monday(today),weeks=Array.from({length:8},(_,i)=>{const start=addDays(m,-7*(7-i)),end=addDays(start,6),ws=state.workouts.filter(w=>w.sport==='run'&&w.date>=start&&w.date<=end&&w.status!=='cancelled');return {start,actual:ws.reduce((a,w)=>a+(w.actual?.km||0),0),planned:ws.reduce((a,w)=>a+(w.actual?.plannedKm??w.km),0)};});
    const max=Math.max(1,...weeks.flatMap(w=>[w.actual,w.planned]));const done=state.workouts.filter(w=>w.actual&&w.status==='done').sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time));
    const runs=done.filter(w=>w.sport==='run');const allKm=runs.reduce((a,w)=>a+w.actual.km,0),minutes=done.reduce((a,w)=>a+w.actual.minutes,0);
    return heading('Kijk wat je al hebt gedaan.','Werkelijke trainingen, niet alleen goede voornemens.')+`<div class="progress-grid"><section class="card"><div class="card-header"><div><h2>Hardlopen per week</h2><p>De afgelopen acht kalenderweken</p></div>${icon('chart',22)}</div><div class="chart-bars" role="img" aria-label="Geplande en werkelijk gelopen kilometers per week">${weeks.map(w=>`<div class="bar-group"><div class="bar planned" style="height:${w.planned/max*100}%" title="Gepland: ${num(w.planned)} km"></div><div class="bar" style="height:${w.actual/max*100}%" title="Gelopen: ${num(w.actual)} km"></div><span class="bar-label">${esc(dateLabel(w.start))}</span></div>`).join('')}</div><div class="legend"><span><i class="light"></i>Gepland</span><span><i></i>Gelopen</span></div><details class="faq mt"><summary>Getallen als tabel bekijken</summary><table class="data-table"><thead><tr><th>Week vanaf</th><th>Gepland</th><th>Gelopen</th></tr></thead><tbody>${weeks.map(w=>`<tr><td>${dateLabel(w.start)}</td><td>${num(w.planned)} km</td><td>${num(w.actual)} km</td></tr>`).join('')}</tbody></table></details></section><section class="card"><div class="card-header"><h2>Jouw totaal</h2><span class="tag muted">Alle registraties</span></div><div class="stat-number">${num(allKm)} <small>km hardgelopen</small></div><div class="key-value"><span>Afgeronde activiteiten</span><strong>${done.length}</strong></div><div class="key-value"><span>Sportminuten</span><strong>${num(minutes)}</strong></div><div class="key-value"><span>Langste gelopen afstand</span><strong>${num(Math.max(0,...runs.map(w=>w.actual.km)))} km</strong></div>${btn('Mijn gegevens exporteren','export-json','','ghost compact mt')}</section></div><section class="card mt"><div class="card-header"><h2>Trainingshistorie</h2><span class="tag muted">Laatste 40 activiteiten</span></div><div class="workout-list">${done.length?done.slice(0,40).map(w=>workoutCard(w)).join(''):'<div class="empty">Je eerste afgeronde training verschijnt hier.</div>'}</div></section>`;
  }
  function slotRow(s){return `<div class="slot-row" data-slot-id="${esc(s.id)}"><label>Dag<select name="day">${opts(Object.fromEntries(days.map((x,i)=>[i,x])),s.day)}</select></label><label>Sport<select name="sport">${opts(sports,s.sport)}</select></label><label>Begintijd<input name="time" type="time" value="${esc(s.time)}" required></label><label>Max. minuten<input name="minutes" type="number" min="15" max="300" value="${Number(s.minutes)}" required></label>${btn(icon('trash',16),'remove-slot','aria-label="Sportmoment verwijderen"','ghost icon-btn')}<label class="slot-kind"><input type="checkbox" name="long" ${s.kind==='long'?'checked':''}> Lange duurloop (alleen voor hardlopen)</label></div>`;}
  function settingsPage(){
    const p=state.profile||{name:'',goal:'fit',baseWeeklyKm:'',longestKm:'',pace:6.5,raceDate:'',autoAdapt:true,horizon:12};
    const slots=state.profile?state.slots:[{id:uid(),day:1,time:'18:30',sport:'run',minutes:60,kind:'easy'},{id:uid(),day:3,time:'18:30',sport:'run',minutes:60,kind:'easy'},{id:uid(),day:6,time:'09:30',sport:'run',minutes:90,kind:'long'}];
    return heading(state.profile?'Jouw doel. Jouw spelregels.':'Begin bij waar je nu staat.',state.profile?'Een collega kan dezelfde app gebruiken, met een volledig eigen plan.':'Vul je eigen startniveau in. Voorbeeldmomenten zijn nog geen persoonlijk advies.')+`<div class="settings-grid"><section class="card"><form id="profile-form"><div class="form-error" role="alert"></div><fieldset><legend>Persoonlijk doel</legend><div class="form-grid"><label>Voornaam<input name="name" maxlength="40" value="${esc(p.name)}" placeholder="Jouw voornaam" required></label><label>Mijn doel<select name="goal">${opts(goals,p.goal)}</select></label><label>Doeldatum (optioneel)<input name="raceDate" type="date" value="${esc(p.raceDate)}"><span class="field-help">Een datum forceert geen onhaalbare inhaalslag.</span></label><label>Rustig tempo (minuten per km)<input name="pace" type="number" min="3" max="15" step="0.1" value="${p.pace}" required><span class="field-help">6,5 betekent 6 minuten 30 seconden per km.</span></label><label>Gemiddeld hardlopen per week<input name="baseWeeklyKm" type="number" min="1" max="150" step="0.1" value="${p.baseWeeklyKm}" placeholder="Bijvoorbeeld 18" required><span class="field-help">Je werkelijke gemiddelde van de laatste 4 weken, niet je gewenste aantal.</span></label><label>Recent langste rustige loop (km)<input name="longestKm" type="number" min="1" max="150" step="0.1" value="${p.longestKm}" placeholder="Bijvoorbeeld 7" required><span class="field-help">Een afstand die je recent daadwerkelijk kon lopen.</span></label><label>Vooruit plannen<select name="horizon"><option value="12" ${p.horizon!==24?'selected':''}>12 weken</option><option value="24" ${p.horizon===24?'selected':''}>24 weken</option></select></label><label>Tijdzone<input readonly value="Europe/Amsterdam"><span class="field-help">Zomer- en wintertijd worden meegenomen.</span></label></div></fieldset><div class="form-separator"></div><fieldset><legend>Je vaste sportmomenten</legend><p class="small muted mb">Dit zijn beschikbare momenten. De afstand wordt begrensd door je niveau en beschikbare minuten. Er blijft 10 minuten ruimte rond een hardlooptraining.</p><div id="slot-rows">${slots.map(slotRow).join('')}</div>${btn(icon('plus',15)+' Sportmoment toevoegen','add-slot','','ghost compact')}</fieldset><div class="form-separator"></div><label class="checkline"><input name="autoAdapt" type="checkbox" ${p.autoAdapt?'checked':''}><span>Schema automatisch beoordelen na iedere registratie.<span class="field-help" style="display:block">Bij pijn of ziekte pauzeert de planning altijd, ook als dit uit staat.</span></span></label><div class="notice mt">Opslaan bouwt toekomstige, niet-vastgezette plantrainingen opnieuw op. Historie, handmatige activiteiten en vastgezette trainingen blijven bewaard. Dit schema is bedoeld als indicatieve basisopbouw, niet als wedstrijdgarantie.</div><button type="submit" class="btn primary">${state.profile?'Instellingen opslaan en schema opbouwen':'Mijn eerste schema maken'} ${icon('arrow',16)}</button></form></section><div class="stack"><section class="card"><div class="card-header"><h2>Jij bent de maatstaf.</h2>${icon('target',23)}</div><p class="small muted">Je hoeft geen marathon te willen lopen. Kies fit blijven, een kortere afstand of een langeafstandendoel. Je collega kiest onafhankelijk een eigen doel en eigen sportmomenten.</p><div class="divider"></div><p class="small muted">Vul nooit een hoger startniveau in om een ambitieus doel sneller in het schema te krijgen. Voor volledig beginnende lopers zonder huidige hardloopbasis bevat deze versie nog geen wandel-hardloopprogramma.</p></section><section class="card"><div class="card-header"><h2>Account en privacy</h2>${icon('shield',21)}</div><p class="small muted">${demo?'Je zit in de fictieve demo. Geen gegevens worden naar Supabase verstuurd.':'Je eigen sportgegevens worden opgeslagen in Supabase. Andere toegelaten gebruikers kunnen je planning niet ophalen via de normale app of database-API.'}</p><div class="button-row mt">${btn('Gegevens exporteren','export-json','','compact')}${btn('Uitloggen','logout','','compact')}</div><div class="divider"></div><p class="small muted">De projectbeheerder kan via Supabase beheerrechten gegevens inzien. Er is geen end-to-endversleuteling. Alleen de publieke appbestanden komen op GitHub, geen sportgegevens of wachtwoorden.</p></section><section class="card"><h3>Wat wordt niet automatisch ingelezen?</h3><p class="small muted mt">Deze versie haalt geen activiteiten uit Garmin of Strava op. Vul een gelopen training zelf in. Ook andere afspraken uit je priveagenda worden nog niet als bezette tijden ingelezen.</p></section></div></div>`;
  }
  function detailModal(id){
    const w=state.workouts.find(x=>x.id===id);if(!w)return;const actual=w.actual;
    showModal(w.title,`${dateLabel(w.date,{weekday:'long',year:'numeric'})} om ${w.time}`,`<div class="metric-banner"><div><strong>${num(w.km)} ${w.sport==='run'?'km':''}</strong><span>${w.sport==='run'?'gepland':'Afstand niet gebruikt'}</span></div><div><strong>${num(w.minutes)} min</strong><span>geplande tijdsduur</span></div></div>${tags(w)}${actual?`<div class="notice mt"><strong>Geregistreerd:</strong> ${num(actual.km)} km / ${num(actual.minutes)} minuten. Inspanning ${actual.rpe}/10.${actual.notes?'<br>'+esc(actual.notes):''}</div>`:''}${w.adaptation?`<div class="notice mt">${esc(w.adaptation)}</div>`:''}<p class="small muted mt">${w.kind==='long'?'Rustige duurloop. Afstand is ondergeschikt aan hoe het gaat; forceer de planning niet.':w.sport==='run'?'Rustig hardlopen. Deze basisversie plant geen snelle interval- of wedstrijdtrainingen.':'Dit sportmoment blijft een tijdsblok; prestaties worden niet omgerekend naar hardloopkilometers.'}</p><div class="modal-actions">${['planned','held'].includes(w.status)?btn('Aanpassen','edit',`data-id="${id}"`,''):''}${w.date<=isoDay()&&w.status!=='cancelled'?btn(actual?'Registratie wijzigen':'Training registreren','log',`data-id="${id}"`,'primary'):''}</div>`);
  }
  function logModal(id){
    const w=state.workouts.find(x=>x.id===id);if(!w)return;const a=w.actual;
    if(w.date>isoDay()){detailModal(id);return;}
    showModal('Wat heb je echt gedaan?',`${w.title} - ${dateLabel(w.date,{weekday:'long'})}`,`<div class="metric-banner"><div><strong>${num(a?.plannedKm??w.km)} km</strong><span>oorspronkelijk gepland</span></div><div><strong>${num(a?.plannedMinutes??w.minutes)} min</strong><span>geplande tijdsduur</span></div></div><form id="workout-log" data-id="${id}"><div class="form-error" role="alert"></div><div class="form-grid"><label>Werkelijke afstand (km)<input name="km" type="number" min="0" max="300" step="0.1" value="${a?.km??w.km}" required><span class="field-help">Bij kracht of padel kun je 0 invullen.</span></label><label>Werkelijke duur (minuten)<input name="minutes" type="number" min="0" max="1440" step="1" value="${a?.minutes??w.minutes}" required></label><label>Hoe zwaar voelde het?<select name="rpe">${opts({'1':'1 - zeer licht','2':'2 - heel licht','3':'3 - licht','4':'4 - ontspannen','5':'5 - gemiddeld','6':'6 - stevig','7':'7 - zwaar','8':'8 - erg zwaar','9':'9 - bijna maximaal','10':'10 - maximaal'},a?.rpe??5)}</select></label><label>Reden / hoe ging het?<select name="reason">${opts({normal:'Volgens plan / voelde goed',time:'Minder tijd beschikbaar',fatigue:'Vermoeid / te zwaar',weather:'Weer of omstandigheden',pain:'Pijn of blessure',illness:'Ziek / niet fit',missed:'Training gemist',other:'Andere reden'},a?.reason??'normal')}</select></label><label class="span2">Notitie (optioneel)<textarea name="notes" maxlength="1000" placeholder="Bijvoorbeeld: moest eerder terug voor een afspraak.">${esc(a?.notes||'')}</textarea></label></div><p class="small muted mt">Niet gesport? Vul 0 km en 0 minuten in. De planner maakt geen inhaalschuld. Bij pijn of ziekte worden toekomstige trainingen gepauzeerd.</p><div class="modal-actions">${btn('Annuleren','close-modal')}<button type="submit" class="btn primary">Opslaan en ${state.profile.autoAdapt?'schema beoordelen':'registreren'}</button></div></form>`);
  }
  function workoutForm(w,isNew){
    showModal(isNew?'Activiteit toevoegen':'Training aanpassen','Dit verandert alleen deze activiteit, niet je wekelijkse vaste momenten.',`<form id="${isNew?'workout-add':'workout-edit'}" ${isNew?'':`data-id="${w.id}"`}><div class="form-error" role="alert"></div><div class="form-grid"><label class="span2">Naam<input name="title" maxlength="80" value="${esc(w.title||'')}" required></label><label>Sport<select name="sport">${opts(sports,w.sport||'run')}</select></label><label>Datum<input name="date" type="date" value="${esc(w.date)}" required></label><label>Begintijd<input name="time" type="time" value="${esc(w.time||'18:30')}" required></label><label>Duur (minuten)<input name="minutes" type="number" min="15" max="300" value="${w.minutes||45}" required></label><label>Afstand (km)<input name="km" type="number" min="0" max="100" step="0.1" value="${w.km||0}" required></label><label>Soort loop<select name="kind">${opts({easy:'Rustig / gewone activiteit',long:'Lange duurloop'},w.kind||'easy')}</select></label><label class="checkline span2"><input name="locked" type="checkbox" ${w.locked?'checked':''}><span>Deze hele training vastzetten, ook de afstand.<span class="field-help" style="display:block">Normaal blijven alleen datum en tijd vast. Een veiligheidspauze geldt ook voor vastgezette trainingen.</span></span></label></div><div class="modal-actions">${isNew?'':btn('Verwijderen','cancel-workout',`data-id="${w.id}"`,'danger')}${btn('Annuleren','close-modal')}<button type="submit" class="btn primary">${isNew?'Activiteit toevoegen':'Wijziging opslaan'}</button></div></form>`);
  }
  function shareModal(){
    showModal('Je sportagenda, ook in je eigen agenda.','Een prive-abonnement voor Apple Agenda, Google Agenda of Outlook.',`<div class="notice">Dit is een koppeling in <strong>een richting</strong>: SportKompas &rarr; je agenda. Wijzigingen verschijnen na verversen door je agenda-app, niet gegarandeerd direct. Een agenda-afspraak wijzigen stuurt niets terug naar SportKompas.</div><label class="checkline"><input id="share-minimal" type="checkbox" checked><span>Minimale informatie delen: alleen "Sporttraining" en datum/tijd.<span class="field-help" style="display:block">Zonder dit vinkje worden sportnaam en geplande afstand zichtbaar. Nooit je notities, inspanning, e-mail of klachtreden.</span></span></label><div class="button-row mt">${btn(icon('lock',15)+' Nieuwe privelink maken','create-share',demo?'disabled':'','primary')}${btn('Bestaande link intrekken','revoke-share',demo?'disabled':'','danger')}</div><p class="small muted mt">Een nieuwe link vervangt de vorige. Iedereen met de link kan deze beperkte agenda lezen. Behandel de link als een wachtwoord. Kopieer hem nu: de server bewaart alleen een hash.</p>${demo?'<div class="notice mt">In de demo kun je een agenda-bestand downloaden. Het live abonnement werkt pas na installatie van de Supabase-functies.</div>':''}<div id="share-result">${shareUrl?linkHTML(shareUrl):''}</div><div class="divider"></div><details class="faq"><summary>Toevoegen aan mijn agenda</summary><p><strong>iPhone / iPad:</strong> Agenda &rarr; Agenda\'s &rarr; Voeg agenda toe &rarr; Voeg agenda-abonnement toe. Plak de link en kies je account.</p><p><strong>Google Agenda:</strong> op een computer bij Andere agenda\'s op + klikken &rarr; Via URL. Plak de HTTPS-link.</p><p><strong>Outlook:</strong> Agenda toevoegen &rarr; Abonneren via internet. Plak de HTTPS-link.</p><p>Je agenda-app bepaalt het verversmoment. Een ingetrokken link stopt toekomstige toegang, maar wist eerder gekopieerde informatie niet.</p></details><div class="divider"></div><div class="button-row">${btn('Los .ics-bestand downloaden','export-ics','','compact')}</div><p class="small muted mt">Een los bestand is een momentopname. Het synchroniseert daarna niet.</p>`);
  }
  function linkHTML(url){return `<div class="link-box"><label>Persoonlijke agenda-URL<input id="feed-url" readonly value="${esc(url)}"></label><div class="button-row">${btn('Kopieer link','copy-share','','primary compact')}<a class="btn compact" href="${esc(url.replace(/^https:/,'webcal:'))}">Open als agenda-abonnement</a></div></div>`;}
  function download(text,type,name){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function openRecover(){showModal('Wachtwoord herstellen','Gebruik je eigen e-mailadres. Je krijgt een link als het account bestaat.',`<form id="recover-form"><div class="form-error" role="alert"></div><label>E-mailadres<input name="email" type="email" autocomplete="username" required></label><div class="modal-actions">${btn('Annuleren','close-modal')}<button type="submit" class="btn primary">Herstellink sturen</button></div></form>`);}
  function openPassword(){showModal('Stel je wachtwoord in','Kies een sterk, uniek wachtwoord voor dit persoonlijke account.',`<form id="password-form"><div class="form-error" role="alert"></div><label>Nieuw wachtwoord<input name="password" type="password" minlength="12" autocomplete="new-password" required></label><label class="mt">Herhaal wachtwoord<input name="confirm" type="password" minlength="12" autocomplete="new-password" required></label><div class="modal-actions"><button type="submit" class="btn primary">Wachtwoord opslaan</button></div></form>`,{locked:true});}
  async function sync(silent=false){if(demo){if(!silent)toast('Dit is een lokale demo; er is niets naar Supabase verstuurd.');return;}if(!state||busy)return;try{const data=await SK.DB.load();state=data.state;syncLabel='Gesynchroniseerd';render();if(!silent)toast('Je nieuwste gegevens zijn geladen.');}catch(e){if(/sessie|geen toegang/.test(e.message)){await SK.DB.logout();state=null;renderAuth();}if(!silent)toast(e.message);}}
  async function handleAction(el){
    const action=el.dataset.action,id=el.dataset.id;
    if(busy&&action!=='copy-share')return;
    if(action==='close-modal'){closeModal();return;}
    if(action==='start-demo'){demo=true;state=SK.demoState();view='overview';anchor=selectedDay=isoDay();render();return;}
    if(action==='reset-demo'){if(confirm('Fictieve demo terugzetten? Je wijzigingen in deze demo verdwijnen.')){state=SK.demoState();render();}return;}
    if(action==='recover'){openRecover();return;}
    if(action==='logout'){if(!demo)await SK.DB.logout();demo=false;state=null;shareUrl='';closeModal();renderAuth();return;}
    if(!state)return;
    if(action==='nav'){view=el.dataset.view;render();scrollTo(0,0);return;}
    if(action==='sync'){await sync();return;}
    if(action==='day'){selectedDay=el.dataset.date;render();return;}
    if(action==='detail'){detailModal(id);return;}
    if(action==='log'){logModal(id);return;}
    if(action==='edit'){const w=state.workouts.find(x=>x.id===id);if(w)workoutForm(w,false);return;}
    if(action==='add-workout'){workoutForm({date:el.dataset.date||isoDay(),title:'Extra sportmoment',sport:'run',time:'18:30',minutes:45,km:5},true);return;}
    if(action==='add-slot'){document.getElementById('slot-rows')?.insertAdjacentHTML('beforeend',slotRow({id:uid(),day:0,time:'18:30',minutes:45,sport:'strength',kind:'easy'}));return;}
    if(action==='remove-slot'){el.closest('.slot-row').remove();return;}
    if(action==='share'){if(!state.profile){toast('Maak eerst je persoonlijke schema.');return;}shareModal();return;}
    if(action==='create-share'){
      if(demo)return;el.disabled=true;
      try{const data=await SK.DB.invoke('calendar-link',{action:'create',minimal:document.getElementById('share-minimal').checked});const u=new URL(data.url);if(u.origin!==new URL(SPORT_CONFIG.supabaseUrl).origin)throw new Error('Onverwachte agenda-URL.');shareUrl=data.url;document.getElementById('share-result').innerHTML=linkHTML(shareUrl);toast('Privelink gemaakt. Een eventuele oude link is ongeldig.');}finally{el.disabled=false;}return;
    }
    if(action==='revoke-share'){if(demo)return;if(!confirm('De bestaande agenda-link intrekken? Je agenda kan daarmee daarna niet meer verversen.'))return;await SK.DB.invoke('calendar-link',{action:'revoke'});shareUrl='';document.getElementById('share-result').innerHTML='';toast('De agendalink is ingetrokken.');return;}
    if(action==='copy-share'){try{await navigator.clipboard.writeText(shareUrl);toast('Agendalink gekopieerd.');}catch{document.getElementById('feed-url')?.select();toast('Selecteer en kopieer de link met je kopieerfunctie.');}return;}
    if(action==='export-ics'){download(SK.calendarText(state,{owner:demo?'demo':SK.DB.user?.id,minimal:document.getElementById('share-minimal')?.checked??true}),'text/calendar;charset=utf-8','sportkompas-agenda.ics');toast('Momentopname gedownload; dit bestand synchroniseert niet.');return;}
    if(action==='export-json'){download(JSON.stringify({exportedAt:new Date().toISOString(),state},null,2),'application/json','sportkompas-backup-'+isoDay()+'.json');toast('Persoonlijke gegevens gedownload. Bewaar dit bestand veilig.');return;}
    if(action==='cal-mode'){calendarMode=el.dataset.mode;render();return;}
    if(action==='cal-today'){anchor=isoDay();render();return;}
    if(action==='cal-prev'||action==='cal-next'){const delta=action==='cal-prev'?-1:1;if(calendarMode==='week')anchor=addDays(anchor,delta*7);else{const d=new Date(anchor.slice(0,7)+'-01T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+delta);anchor=d.toISOString().slice(0,10);}render();return;}
    if(action==='recalculate'){const c=clone(state);SK.adaptPlan(c);await commit(c,'Schema opnieuw beoordeeld.');return;}
    if(action==='resume'){showModal('Bewust opnieuw beginnen','Bevestig zelf een passend huidig startniveau. De app kan herstel niet medisch beoordelen.',`<form id="resume-form"><div class="form-error" role="alert"></div><div class="notice warning">Hervat niet om gemiste kilometers in te halen. Bespreek aanhoudende klachten met een deskundige.</div><div class="form-grid"><label>Passend weektotaal (km)<input name="weekly" type="number" min="1" max="150" step="0.1" placeholder="Jouw huidige basis" required></label><label>Passende langste loop (km)<input name="longest" type="number" min="1" max="150" step="0.1" placeholder="Jouw huidige niveau" required></label></div><label class="checkline mt"><input type="checkbox" required><span>Ik beoordeel zelf of hervatten passend is en bevestig dit startniveau.</span></label><div class="modal-actions">${btn('Op pauze blijven','close-modal')}<button type="submit" class="btn primary">Hervatten en opnieuw plannen</button></div></form>`);return;}
    if(action==='cancel-workout'){if(!confirm('Deze geplande activiteit verwijderen? De agendakoppeling krijgt een annulering.'))return;const c=clone(state);SK.cancelWorkout(c,id);await commit(c,'Activiteit verwijderd.');closeModal();return;}
  }
  document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(el){event.preventDefault();handleAction(el).catch(e=>toast(e.message));}else if(event.target.classList.contains('modal-overlay')&&!modalLocked)closeModal();});
  document.addEventListener('keydown',event=>{if(!modalRoot.firstChild)return;if(event.key==='Escape'&&!modalLocked)closeModal();if(event.key==='Tab'){const nodes=[...modalRoot.querySelectorAll('button:not(:disabled),a,input:not(:disabled),select:not(:disabled),textarea:not(:disabled)')].filter(x=>x.offsetParent!==null);const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
  document.addEventListener('submit',async event=>{
    event.preventDefault();if(busy)return;const form=event.target,fd=new FormData(form);busy=true;const submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;
    let shouldClose=false;
    try{
      if(form.id==='login-form'){const result=await SK.DB.login(String(fd.get('email')).trim(),String(fd.get('password')));demo=false;state=result.state;view=state.profile?'overview':'settings';render();}
      else if(form.id==='profile-form'){
        const slots=[...form.querySelectorAll('.slot-row')].map(row=>({id:row.dataset.slotId,day:Number(row.querySelector('[name=day]').value),sport:row.querySelector('[name=sport]').value,time:row.querySelector('[name=time]').value,minutes:Number(row.querySelector('[name=minutes]').value),kind:row.querySelector('[name=long]').checked?'long':'easy'}));
        const p={name:String(fd.get('name')).trim(),goal:fd.get('goal'),raceDate:fd.get('raceDate')||'',baseWeeklyKm:Number(fd.get('baseWeeklyKm')),longestKm:Number(fd.get('longestKm')),pace:Number(fd.get('pace')),autoAdapt:fd.get('autoAdapt')==='on',timezone:'Europe/Amsterdam',horizon:Number(fd.get('horizon'))};
        SK.validateProfile(p,slots);if(p.raceDate&&p.raceDate<isoDay())throw new Error('Kies een toekomstige doeldatum of laat deze leeg.');
        const first=!state.profile,c=clone(state);c.profile=p;c.slots=slots;SK.generatePlan(c,{weeks:p.horizon});await commit(c,'Je persoonlijke schema is opgeslagen.');if(first){view='overview';render();scrollTo(0,0);}
      }
      else if(form.id==='workout-log'){const c=clone(state);SK.logWorkout(c,form.dataset.id,{km:Number(fd.get('km')),minutes:Number(fd.get('minutes')),rpe:Number(fd.get('rpe')),reason:fd.get('reason'),notes:fd.get('notes')});await commit(c,c.hold?'Training opgeslagen. De planning staat op pauze.':'Training opgeslagen. Bekijk de aanpassingen bij Coach.');shouldClose=true;}
      else if(form.id==='workout-add'||form.id==='workout-edit'){
        const c=clone(state),patch={title:String(fd.get('title')).trim(),date:fd.get('date'),time:fd.get('time'),sport:fd.get('sport'),kind:fd.get('kind'),minutes:Number(fd.get('minutes')),km:Number(fd.get('km')),locked:fd.get('locked')==='on'};
        if(!patch.title)throw new Error('Vul een naam in.');
        if(form.id==='workout-add'){const w=SK.makeWorkout(patch);SK.checkMove(c,w);if(c.hold)w.status='held';c.workouts.push(w);SK.changeLog(c,'Activiteit toegevoegd','Handmatig sportmoment toegevoegd; niet meegerekend als nieuwe hardloopbasis.',[],new Date());}
        else SK.editWorkout(c,form.dataset.id,patch);
        await commit(c,'Activiteit opgeslagen.');shouldClose=true;
      }
      else if(form.id==='recover-form'){await SK.DB.recover(String(fd.get('email')).trim());toast('Als dit account bestaat, ontvang je een herstellink.');shouldClose=true;}
      else if(form.id==='password-form'){if(fd.get('password')!==fd.get('confirm'))throw new Error('De wachtwoorden zijn niet hetzelfde.');await SK.DB.password(String(fd.get('password')));recovery=false;history.replaceState(null,'',location.pathname);const result=await SK.DB.load();demo=false;state=result.state;view=state.profile?'overview':'settings';render();toast('Je wachtwoord is ingesteld.');shouldClose=true;}
      else if(form.id==='resume-form'){const c=clone(state);SK.resumePlan(c,fd.get('weekly'),fd.get('longest'));await commit(c,'Je planning is opnieuw opgebouwd.');shouldClose=true;}
      else if(form.id==='coach-form'){
        const question=String(fd.get('question')||'').trim();if(!question||question.length>1200||fd.get('consent')!=='on')throw new Error('Vul een vraag in en geef toestemming voor deze AI-aanroep.');
        let answer;
        if(demo)answer='Dit is een lokale demonstratie, geen antwoord van een taalmodel.\n\nDe automatische planner gebruikt je geregistreerde afstand, inspanning en reden. Bij 5 van 10 km door tijdgebrek kan een komende vergelijkbare loop worden teruggebracht, zonder de ontbrekende 5 km elders toe te voegen. De precieze wijzigingen staan links in het overzicht.\n\nVoor echte AI-uitleg moet de beheerder de optionele ai-coach-functie activeren. Dat is niet nodig voor het automatisch aanpassen van je schema.';
        else{if(!SPORT_CONFIG.enableAI)throw new Error('De AI-koppeling is nog niet geactiveerd.');const result=await SK.DB.invoke('ai-coach',{question,consent:true});answer=result.answer;}
        const box=document.getElementById('ai-answer');box.className='ai-output';box.textContent=answer;
      }
    }catch(e){showError(form,e.message);}
    finally{busy=false;if(submit?.isConnected)submit.disabled=false;if(shouldClose)closeModal();}
  });
  async function boot(){
    renderAuth();
    if(SK.DB.configured())try{
      const c=await SK.DB.connect();c.auth.onAuthStateChange((event)=>{
        if(event==='PASSWORD_RECOVERY'){recovery=true;setTimeout(openPassword,0);}
        if(event==='SIGNED_OUT'&&!demo){state=null;shareUrl='';modalRoot.innerHTML='';document.body.style.overflow='';renderAuth();}
      });
      const {data}=await c.auth.getSession();
      if(data.session){if(recovery)openPassword();else{const result=await SK.DB.load();state=result.state;view=state.profile?'overview':'settings';render();}}
    }catch(e){toast(e.message);}
    if('serviceWorker'in navigator&&['https:','http:'].includes(location.protocol)&&!globalThis.SPORT_PREVIEW)navigator.serviceWorker.register('./sw.js').catch(()=>{});
  }
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&state&&!demo&&!busy&&!modalRoot.firstChild&&Date.now()-lastFocusSync>30000){lastFocusSync=Date.now();sync(true);}});
  window.addEventListener('offline',()=>{if(state){syncLabel='Offline';render();toast('Offline. Gegevens kunnen pas met verbinding worden opgeslagen.');}});
  window.addEventListener('online',()=>{if(state&&!demo&&!modalRoot.firstChild)sync(true);});
  boot();
})(globalThis.SK ||= {});
